func memoize<T: Hashable, U>(_ f: @escaping (T) -> U) -> (T) -> U {
    var cache = [T: U]()
    return { x in
        if let cached = cache[x] { return cached }
        let result = f(x)
        cache[x] = result
        return result
    }
}
let fib = memoize { (n: Int) -> Int in n <= 1 ? n : n }
print(fib(5))

enum ParseFehler: Error { case ungültig }
func parse(_ s: String) throws -> [Int] {
    return try s.components(separatedBy: ",").map {
        guard let n = Int($0.trimmingCharacters(in: .whitespaces)) else {
            throw ParseFehler.ungültig
        }
        return n
    }
}
