// Swift 6 Typed Throws:
enum ParseError: Error { case ungültig, leer }
func parse(_ s: String) throws(ParseError) -> Int {
    guard !s.isEmpty else { throw ParseError.leer }
    guard let n = Int(s) else { throw ParseError.ungültig }
    return n
}
do {
    let n = try parse("abc")
} catch ParseError.ungültig {
    print("Ungültige Eingabe")
}

enum NetworkError: Error { case offline, timeout, serverError(Int) }
enum AppError: Error {
    case network(NetworkError)
    case parsing(String)
    case unknown
}
func ladeDaten() throws -> Data {
    throw AppError.network(.timeout)
}

func ladeOderStandard() -> Result<Data, NetworkError> {
    do {
        let data = try ladeDaten()
        return .success(data)
    } catch let e as NetworkError {
        return .failure(e)
    } catch {
        return .failure(.serverError(0))
    }
}
let result = ladeOderStandard()
switch result {
case .success(let data): print(data.count)
case .failure(let e): print(e)
}

let result: Result<Int, Error> = .success(42)
let wert = try result.___
print(wert)

func transform<T, E: Error, R>(
    _ result: Result<T, E>,
    _ f: (T) throws -> R
) -> Result<R, Error> {
    switch result {
    case .success(let v): return Result { try f(v) }
    case .failure(let e): return .failure(e)
    }
}

enum Fehler: Error, CustomStringConvertible {
    case a(String)
    case b(Int)
    var description: String {
        switch self {
        case .a(let msg): return "Fehler A: \(msg)"
        case .b(let code): return "Fehler B: Code \(code)"
        }
    }
}
print(Fehler.a("Verbindung abgebrochen"))

func rethrowing<T>(
    _ array: [T],
    _ op: (T) throws -> Void
) rethrows {
    for element in array {
        try op(element)
    }
}
try rethrowing([1, 2, 3]) { print($0) } // Kein try nötig wenn op nicht throws
rethrowing([1, 2, 3]) { print($0) }

struct Validator {
    static func validate(_ n: Int) -> Result<Int, ValidationError> {
        guard n > 0 else { return .failure(.negativ) }
        guard n < 100 else { return .failure(.zuGroß) }
        return .success(n)
    }
}
enum ValidationError: Error { case negativ, zuGroß }
let results = [-1, 50, 200].map { Validator.validate($0) }
let erfolge = results.compactMap { try? $0.get() }
