struct CountDown: AsyncSequence {
    typealias Element = Int
    let von: Int
    struct AsyncIterator: AsyncIteratorProtocol {
        var aktuell: Int
        mutating func next() async -> Int? {
            guard aktuell > 0 else { return nil }
            defer { aktuell -= 1 }
            return aktuell
        }
    }
    func makeAsyncIterator() -> AsyncIterator { .init(aktuell: von) }
}
Task {
    for await n in CountDown(von: 3) { print(n) }
}

