@Observable
final class AppViewModel {
    private let repo: any Repository<Task>
    var tasks: [Task] = []
    var isLoading = false
    var error: Error?

    init(repo: any Repository<Task>) { self.repo = repo }

    func loadTasks() async {
        isLoading = true
        defer { isLoading = false }
        do {
            tasks = try await repo.findAll()
        } catch {
            self.error = error
        }
    }
}

struct Task: Identifiable, Codable, Sendable {
    let id: UUID
    var title: String
    var completed: Bool
    var priority: Priority

    enum Priority: Int, Codable, Comparable {
        case niedrig = 0, mittel, hoch
        static func < (lhs: Self, rhs: Self) -> Bool { lhs.rawValue < rhs.rawValue }
    }
}

class TaskViewModelTests: XCTestCase {
    var sut: AppViewModel!
    var mockRepo: MockTaskRepository!

    override func setUp() async throws {
        mockRepo = MockTaskRepository()
        sut = AppViewModel(repo: mockRepo)
    }

    func testLoadTasks() async throws {
        mockRepo.tasks = [Task(id: .init(), title: "Test", completed: false, priority: .hoch)]
        await sut.loadTasks()
        XCTAssertEqual(sut.tasks.count, 1)
        XCTAssertFalse(sut.isLoading)
    }
}

extension [Task] {
    var hochpriorität: [Task] {
        filter { $0.priority == .hoch }.sorted { $0.title < $1.title }
    }
    var statistik: (gesamt: Int, erledigt: Int, offen: Int) {
        let erledigt = filter { $0.completed }.count
        return (count, erledigt, count - erledigt)
    }
}

actor TaskManager {
    private let repo: any Repository<Task>
    private var cache: [UUID: Task] = [:]

    init(repo: any Repository<Task>) { self.repo = repo }

    func save(_ task: Task) async throws {
        try await repo.save(task)
        cache[task.id] = task
    }

    func findById(_ id: UUID) async throws -> Task? {
        if let cached = cache[id] { return cached }
        let task = try await repo.findById(id)
        if let task { cache[id] = task }
        return task
    }
}

